/*
 * When the engine context exists and g_BattleMagicShieldLoadedResTable is empty, builds magic/seald with a default-
 * duration record and creates resource type 4 using g_BattleMagicShieldResourceDefs.
 */
// FUNCTION: FF7 0x00532b10
void __cdecl BattleFx_MagicLoadResShield(void)
{
    GfxModelTableBank *ownerHandle;
    GfxResourceRequest recordBuf;
    int kind;
    char resourceName[200];
    GfxResourceRequest *pRequest;
    int sealdDefs;

    if (g_pBattle3dScene != 0 && g_BattleMagicShieldLoadedResTable == 0) {
        kind = 4;
        sealdDefs = (int)&g_BattleMagicShieldResourceDefs;
        ownerHandle = (GfxModelTableBank *)(g_pBattle3dScene->modelTableBank);
        pRequest = &recordBuf;
        Gfx_InitResourceRequest(pRequest);
        pRequest->groupTag = 0;
        // STRING: FF7 0x008a246c
        pRequest->resourcePath = BattleFx_BuildResourcePath("magic/seald", resourceName);
        Gfx_LoadModelTableIfAbsent(kind, sealdDefs, pRequest, &g_BattleMagicShieldLoadedResTable, ownerHandle);
    }
}

/*
 * Entry point for the Seald magic effect: calls BattleFx_MagicLoadResShield, then forwards both
 * arguments to BattleFx_MagicBeginShield.
 */
// FUNCTION: FF7 0x00532ba0
void __cdecl BattleFx_MagicEnterShield(int targetMask, int actorIdx)
{
    BattleFx_MagicLoadResShield();
    BattleFx_MagicBeginShield(targetMask, actorIdx);
}

/*
 * Allocates BattleFx_SelectDrawListBuffer and stores its slot address, records the first set bit
 * among the low ten bits of targetMask if one exists, allocates BattleFx_MagicShieldSetupTask, and dispatches opcode 0x20
 * with targetMask entity pan and sound 0x16D.
 */
// FUNCTION: FF7 0x00532bba
void __cdecl BattleFx_MagicBeginShield(int targetMask, int actorIdx)
{
    int bitIdx, count;

    *(int *)&g_BattleFxDrawListBufferTaskSlotPtr = (int)BATTLE_NEW_TASK_SLOT(BattleFx_SelectDrawListBuffer);
    bitIdx = 0;
    count = 0;
    for (; bitIdx < 0xA; bitIdx++) {
        if ((targetMask & 1 << bitIdx) != 0) {
            count++;
            if (count == 1) {
                g_BattleMagicShieldTargetActor = bitIdx;
            }
        }
    }
    Battle_AllocateResourceSlot(BattleFx_MagicShieldSetupTask);
    Battle_DispatchSfxOpcodeDirect(SOUND_SFX_PLAY_1, Battle_ComputePanForEntity(targetMask), 0x16D);
}

