            ((MagicShieldFaceMotion *)&g_BattleMagicShieldMotionData)[frameNumber].velocityY -= ((MagicShieldFaceMotion *)&g_BattleMagicShieldMotionData)[frameNumber].accelY;
            ((MagicShieldFaceMotion *)&g_BattleMagicShieldMotionData)[frameNumber].velocityZ -= ((MagicShieldFaceMotion *)&g_BattleMagicShieldMotionData)[frameNumber].accelZ;
